const rows = $input.all().flatMap(i => (i.json && i.json.results) || []);
const esc = s => String(s==null?'':s).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split('"').join('&quot;');
const num = v => (v==null? null : Number(v));
const deals = rows.map(p => {
  const pr = p.properties||{};
  const t = ((pr['สินค้า']||{}).title)||[];
  return {
    id: p.id,
    name: t.map(x=>x.plain_text).join('').trim(),
    link: (pr['ลิงก์Affiliate']||{}).url || '',
    full: num((pr['ราคาเต็ม']||{}).number),
    sale: num((pr['ราคาลด']||{}).number),
    cat : ((pr['หมวด']||{}).select||{}).name || '',
    when: ((pr['โพสต์เมื่อ']||{}).date||{}).start || '',
    img : (pr['รูป']||{}).url || ''
  };
}).filter(d => d.name && d.link && d.name.indexOf('ทดสอบ') === -1);
// click tracking: every card goes through /webhook/go?d=<notion page id>, which counts and 302s
const sd = $getWorkflowStaticData('global');
const links = {};
for (const d of deals) { const host = ((String(d.link).match(/^https?:\/\/([^\/?#]+)/) || [])[1]) || ''; links[d.id] = { url: d.link, name: d.name, host }; }   // no URL global in the Code sandbox
const shown = deals.slice(0, 120);   // newest first (Notion sort); older ones are mostly expired flash sales

const money = n => (n==null? '' : Number(n).toLocaleString('th-TH',{maximumFractionDigits:2}));
const tn = u => {
  if(!u || u.indexOf('susercontent.com/file/') < 0) return u;
  const seg = u.slice(u.lastIndexOf('/')+1);
  if(seg.indexOf('.') > -1 || seg.slice(-3) === '_tn') return u;
  return u + '_tn';
};
const cards = shown.map(d => {
  const off = (d.full && d.sale && d.full > d.sale) ? Math.round((1 - d.sale/d.full)*100) : null;
  const price = d.sale!=null ? ('<span class="now">' + money(d.sale) + ' ฿</span>' + (d.full!=null&&d.full>d.sale ? ' <span class="was">' + money(d.full) + ' ฿</span>' : '')) : '';
  const thumb = d.img
    ? '<img class="thumb" src="' + esc(tn(d.img)) + '" data-o="' + esc(d.img) + '" alt="" loading="lazy" decoding="async" referrerpolicy="no-referrer" onerror="if(this.dataset.f){this.remove()}else{this.dataset.f=1;this.src=this.dataset.o}">'
    : '';
  return '<a class="card" href="/webhook/go?d=' + encodeURIComponent(d.id) + '" target="_blank" rel="noopener nofollow">' +
    (off!=null ? '<span class="off">-' + off + '%</span>' : '') +
    thumb +
    '<div class="body">' +
    (d.cat ? '<span class="chip">' + esc(d.cat) + '</span>' : '') +
    '<div class="name">' + esc(d.name) + '</div>' +
    '<div class="price">' + price + '</div>' +
    '<div class="go">ดูดีล →</div></div></a>';
}).join('');
const page = '<!doctype html><html lang="th"><head><meta charset="utf-8">' +
  '<meta name="viewport" content="width=device-width,initial-scale=1">' +
  '<title>ป้ายยาดีลเด็ด — รวมดีลล่าสุด</title>' +
  '<meta name="robots" content="noindex">' +
  '<style>' +
  ':root{--bg:#faf6f0;--sf:#fffcf8;--sf2:#f3eadf;--ln:#dfd1bf;--tx:#382c22;--mu:#6f5f51;--ac:#8b5e3c}' +
  '*{box-sizing:border-box}body{margin:0;padding:20px 14px 48px;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Noto Sans Thai",sans-serif;color:var(--tx);background:radial-gradient(1200px 600px at 80% -10%,#f1e3d3 0%,transparent 60%),radial-gradient(900px 500px at -10% 110%,#eaddce 0%,transparent 55%),var(--bg)}' +
  '.wrap{max-width:560px;margin:0 auto}' +
  'h1{font-size:22px;margin:0 0 4px;display:flex;align-items:center;gap:8px}' +
  '.sub{color:var(--mu);font-size:14px;margin:0 0 20px}' +
  '.card{position:relative;display:flex;gap:12px;align-items:flex-start;background:linear-gradient(180deg,var(--sf2),var(--sf));border:1px solid var(--ln);border-left:4px solid var(--ac);border-radius:14px;padding:14px 16px;margin-bottom:12px;text-decoration:none;color:inherit;box-shadow:0 6px 18px rgba(56,44,34,.10)}' +
  '.card:active{transform:scale(.99)}' +
  '.chip{display:inline-block;font-size:11px;color:var(--mu);border:1px solid var(--ln);border-radius:99px;padding:2px 9px;margin-bottom:8px}' +
  '.off{position:absolute;top:12px;right:14px;background:var(--ac);color:#fffcf8;font-size:12px;font-weight:700;border-radius:8px;padding:3px 8px}' +
  '.body{flex:1;min-width:0}' +
  '.thumb{flex:0 0 92px;width:92px;height:92px;border-radius:10px;object-fit:cover;background:var(--sf2);border:1px solid var(--ln);display:block}' +
  '@media(max-width:380px){.thumb{flex-basis:74px;width:74px;height:74px}}' +
  '.name{font-weight:600;line-height:1.45;margin-bottom:8px;padding-right:52px}' +
  '.now{font-size:19px;font-weight:800;color:var(--ac)}' +
  '.was{color:var(--mu);text-decoration:line-through;font-size:13px;margin-left:4px}' +
  '.go{margin-top:10px;font-size:13px;font-weight:700;color:var(--ac)}' +
  '.pager{display:none;align-items:center;justify-content:center;gap:12px;margin:18px 0 4px;color:var(--mu);font-size:13px;flex-wrap:wrap}' +
  '.pager button{font:inherit;font-size:13px;padding:7px 14px;border-radius:9px;cursor:pointer;border:1px solid var(--ln);background:var(--sf);color:var(--tx)}' +
  '.pager button:hover:not(:disabled){border-color:var(--ac);color:var(--ac)}' +
  '.pager button:disabled{opacity:.4;cursor:default}' +
  '.foot{text-align:center;color:var(--mu);font-size:12px;margin-top:24px;line-height:1.8}' +
  '.empty{color:var(--mu);text-align:center;padding:40px 0}' +
  '</style></head><body><div class="wrap">' +
  '<h1>🛒 ป้ายยาดีลเด็ด</h1>' +
  '<p class="sub">ดีลล่าสุด ' + shown.length + ' รายการ' + (deals.length > shown.length ? ' จากทั้งหมด ' + deals.length : '') + ' · แตะการ์ดเพื่อไปที่ร้าน</p>' +
  '<div class="pager" id="pgTop"></div>' +
  (cards || '<div class="empty">ยังไม่มีดีลในตอนนี้</div>') +
  '<div class="pager" id="pgBot"></div>' +
  '<p class="foot">ลิงก์ในหน้านี้เป็นลิงก์ affiliate<br>Telegram @paiyaa_deals · Facebook ป้ายยาดีลเด็ด</p>' +
  '<script>(function(){' +
  'var PER=30,page=0;' +
  'var cards=[].slice.call(document.querySelectorAll(".card"));' +
  'var pages=Math.max(1,Math.ceil(cards.length/PER));' +
  'var bars=[document.getElementById("pgTop"),document.getElementById("pgBot")];' +
  'function bar(pg){' +
  'pg.textContent="";' +
  'var b1=document.createElement("button");b1.textContent="\\u2039 \\u0e22\\u0e49\\u0e2d\\u0e19\\u0e2b\\u0e25\\u0e31\\u0e07";' +
  'b1.disabled=(page===0);b1.onclick=function(){if(page>0){page--;render();}};' +
  'var sp=document.createElement("span");' +
  'sp.textContent=(page*PER+1)+"-"+Math.min(cards.length,(page+1)*PER)+" \\u0e08\\u0e32\\u0e01 "+cards.length+" \\u00b7 \\u0e2b\\u0e19\\u0e49\\u0e32 "+(page+1)+"/"+pages;' +
  'var b2=document.createElement("button");b2.textContent="\\u0e16\\u0e31\\u0e14\\u0e44\\u0e1b \\u203a";' +
  'b2.disabled=(page+1>=pages);b2.onclick=function(){if(page+1<pages){page++;render();}};' +
  'pg.appendChild(b1);pg.appendChild(sp);pg.appendChild(b2);}' +
  'function render(){' +
  'for(var i=0;i<cards.length;i++){cards[i].style.display=(i>=page*PER&&i<(page+1)*PER)?"":"none";}' +
  'for(var k=0;k<bars.length;k++){if(!bars[k])continue;' +
  'if(pages<2){bars[k].style.display="none";}else{bars[k].style.display="flex";bar(bars[k]);}}' +
  'window.scrollTo(0,0);}' +
  'render();})();</script>' +
  '</div></body></html>';
sd.page = page; sd.builtAt = Date.now(); sd.links = links; sd.dealCount = deals.length;
if (!sd.clicks) sd.clicks = {};
return [{ json: { page, cached: false } }];

// Serve the page from workflow static data while it is younger than CACHE_SEC.
// Notion takes ~5 s for 495 rows; the TikTok in-app browser does not wait that long.
// ?refresh=1 forces a rebuild.
const CACHE_SEC = 600;
const sd = $getWorkflowStaticData('global');
const q = ($input.first().json.query) || {};
const age = sd.builtAt ? (Date.now() - sd.builtAt) / 1000 : Infinity;
if (sd.page && age < CACHE_SEC && !q.refresh) return [{ json: { page: sd.page, cached: true, ageSec: Math.round(age) } }];
return [{ json: { cached: false, ageSec: age === Infinity ? null : Math.round(age) } }];

// /webhook/go?d=<notion page id>: count the click, then 302 to the affiliate link.
// Only ids the page builder saw are redirect targets (no open redirect); anything else goes home.
const sd = $getWorkflowStaticData('global');
const q = ($input.first().json.query) || {};
const id = String(q.d || '');
const hit = sd.links && sd.links[id];
// a relative Location is rewritten badly by the redirect node (seen: https://webhook/deals), so build it from the request host
const h = ($input.first().json.headers) || {};
const home = 'https://' + (h['x-forwarded-host'] || h.host || 'n8n.srv1277799.hstgr.cloud') + '/webhook/deals';
if (!hit) return [{ json: { url: home, known: false } }];
if (!sd.clicks) sd.clicks = {};
const c = sd.clicks[id] || { n: 0, first: Date.now(), last: 0 };
c.n += 1; c.last = Date.now();
sd.clicks[id] = c;
return [{ json: { url: hit.url, known: true, n: c.n } }];

// /webhook/deals-stats: which deals get clicked. Static-data only, nothing leaves the box.
const sd = $getWorkflowStaticData('global');
const esc = s => String(s==null?'':s).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
const clicks = sd.clicks || {}; const links = sd.links || {};
const week = Date.now() - 7*86400000;
const rows = Object.keys(clicks).map(id => ({ id, n: clicks[id].n, last: clicks[id].last, name: (links[id]||{}).name || id, host: (links[id]||{}).host || '' }))
  .sort((a,b) => b.n - a.n);
const total = rows.reduce((s,r) => s + r.n, 0);
const recent = rows.filter(r => r.last >= week).reduce((s,r) => s + r.n, 0);
const byHost = {}; for (const r of rows) byHost[r.host] = (byHost[r.host]||0) + r.n;
const fmt = t => t ? new Date(t + 7*3600000).toISOString().replace('T',' ').slice(0,16) : '-';
const tr = rows.slice(0, 200).map(r => '<tr><td>' + esc(r.name).slice(0,70) + '</td><td>' + esc(r.host.replace(/^s\./,'')) + '</td><td class="n">' + r.n + '</td><td>' + fmt(r.last) + '</td></tr>').join('');
const hosts = Object.keys(byHost).map(h => esc(h.replace(/^s\./,'')) + ' ' + byHost[h]).join(' · ');
const page = '<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>สถิติคลิก — ป้ายยาดีลเด็ด</title>' +
 '<style>body{font-family:-apple-system,"Segoe UI","Noto Sans Thai",sans-serif;margin:0;padding:20px 14px;color:#382c22;background:#faf6f0}.wrap{max-width:720px;margin:0 auto}h1{font-size:20px}p{color:#6f5f51;font-size:14px}table{width:100%;border-collapse:collapse;font-size:13px;background:#fffcf8}th,td{padding:8px 6px;border-bottom:1px solid #dfd1bf;text-align:left;vertical-align:top}th{color:#6f5f51;font-weight:600}td.n{text-align:right;font-weight:700;color:#8b5e3c}</style></head><body><div class="wrap">' +
 '<h1>📊 สถิติคลิก</h1>' +
 '<p>คลิกทั้งหมด <b>' + total + '</b> · 7 วันล่าสุด <b>' + recent + '</b> · ดีลที่เคยถูกคลิก ' + rows.length + ' จาก ' + Object.keys(links).length + '<br>' + (hosts || 'ยังไม่มีคลิก') + '<br>หน้า deals สร้างล่าสุด ' + fmt(sd.builtAt) + ' (เวลาไทย) · ' + (sd.dealCount || 0) + ' ดีล</p>' +
 '<table><tr><th>ดีล</th><th>ร้าน</th><th>คลิก</th><th>ล่าสุด</th></tr>' + (tr || '<tr><td colspan=4>ยังไม่มีคลิก</td></tr>') + '</table>' +
 '</div></body></html>';
return [{ json: { page } }];
